class Order {
  customer: Customer;
  totalCents: number;

  getCustomerDisplay(): string {
    return `${this.customer.firstName} ${this.customer.lastName} (${this.customer.loyaltyTier})`;
  }
}

class Customer {
  firstName: string;
  lastName: string;
  loyaltyTier: string;
}

class Order {
  items: CartItem[];
  customer: Customer;
  calculateTotal(taxService: TaxService, discountService: DiscountService): number {
    return this.items.reduce((sum, item) => {
      const base = item.product.getBasePrice() * item.quantity;
      const tax = taxService.calculateTax(item.product, this.customer.region);
      const discount = discountService.getDiscount(this.customer, item.product);
      return sum + base + tax - discount;
    }, 0);
  }
}

