class Invoice {
  customer: Customer;
  amount: number;
  dueDate: Date;
  calculateLateFee(today: Date): number {
    const daysLate = Math.max(0, Math.ceil((today.getTime() - this.dueDate.getTime()) / DAY));
    return this.customer.lateFeeRate * this.amount * daysLate;
  }
}

// Version B
class Customer {
  lateFeeRate: number;
  calculateLateFeeForInvoice(invoiceAmount: number, dueDate: Date, today: Date): number {
    const daysLate = Math.max(0, Math.ceil((today.getTime() - dueDate.getTime()) / DAY));
    return this.lateFeeRate * invoiceAmount * daysLate;
  }
}
